import{_ as s,o as a,c as r,a3 as o}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Schedules, periods and blocks","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/schedules-blocks.md","filePath":"user/center/schedules-blocks.md"}'),t={name:"user/center/schedules-blocks.md"};function i(n,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="schedules-periods-and-blocks" tabindex="-1">Schedules, periods and blocks <a class="header-anchor" href="#schedules-periods-and-blocks" aria-label="Permalink to &quot;Schedules, periods and blocks&quot;">​</a></h1><h2 id="schedules" tabindex="-1">Schedules <a class="header-anchor" href="#schedules" aria-label="Permalink to &quot;Schedules&quot;">​</a></h2><p>Riding, visit and trainer schedules say <strong>which days and hours</strong> can be booked. Weekdays count from <strong>Sunday</strong>. A window can run until the end of the day (24:00) but a booking cannot cross midnight. Times are UTC.</p><h2 id="capacity" tabindex="-1">Capacity <a class="header-anchor" href="#capacity" aria-label="Permalink to &quot;Capacity&quot;">​</a></h2><ul><li>Riding and training: a maximum number of <strong>tickets per hour</strong>. Training capacity is per trainer, across all their services.</li><li>Visits: a maximum number of <strong>tickets per day</strong>, shared between entry types.</li><li>Leaving a capacity empty means unlimited.</li></ul><h2 id="service-blocks" tabindex="-1">Service blocks <a class="header-anchor" href="#service-blocks" aria-label="Permalink to &quot;Service blocks&quot;">​</a></h2><p>A <strong>block</strong> closes a time range so nothing can be booked.</p><ul><li>Attach it to <strong>one service</strong>, or leave the service empty to close the <strong>whole center</strong>.</li><li>Center-wide blocks need the permission to manage all services.</li><li>A booking is refused if it overlaps a block.</li></ul><h2 id="periods" tabindex="-1">Periods <a class="header-anchor" href="#periods" aria-label="Permalink to &quot;Periods&quot;">​</a></h2><p><strong>Periods</strong> set gender-specific hours where your center offers them.</p><h2 id="resort-closures" tabindex="-1">Resort closures <a class="header-anchor" href="#resort-closures" aria-label="Permalink to &quot;Resort closures&quot;">​</a></h2><p>For resorts you can close all bookings of a type for a range, for example during maintenance.</p>',12)])])}const b=s(t,[["render",i]]);export{p as __pageData,b as default};
